import { Candle } from '@trade-automation/contracts';
import { bollinger, ema, macd, rsi, sma, stochastic } from '../src';
import type { IndicatorValue } from '../src';
import reference from './fixtures/talib-reference.json';

/**
 * T-027 — every defined value of the six indicators against TA-Lib on a 300-bar random walk
 * (test/fixtures/talib-reference.json, generated by scripts/talib-reference.py with TA-Lib 0.8.1).
 * Values match to 1e-9 relative, and each series starts at exactly TA-Lib's first defined bar
 * (except %K, see below).
 */
type Ref = { openTime: number; open: number; high: number; low: number; close: number };
const bars: Candle[] = (reference.bars as Ref[]).map((b) => ({
  instrument: 'binance:BTCUSDT', timeframe: '1m', ...b, volume: 1, closed: true, source: 'venue-rest',
}));

function expectMatches(series: IndicatorValue[], ref: (number | null)[], label: string) {
  const first = ref.findIndex((v) => v !== null);
  expect({ label, first: bars.findIndex((b) => b.openTime === series[0]?.time) }).toEqual({ label, first });
  expect({ label, length: series.length }).toEqual({ label, length: ref.length - first });
  series.forEach((point, j) => {
    const want = ref[first + j] as number;
    expect(point.time).toBe(bars[first + j].openTime);
    if (Math.abs(point.value - want) > 1e-9 * Math.max(1, Math.abs(want))) {
      throw new Error(`${label}[${first + j}]: expected ${want}, got ${point.value}`);
    }
  });
}

describe('new indicators against TA-Lib (reference fixture)', () => {
  it('was generated by TA-Lib', () => {
    expect(reference.source).toMatch(/^TA-Lib /);
    expect(bars).toHaveLength(300);
  });

  it('SMA(20) = TA-Lib SMA; first defined at bar 19', () => {
    expectMatches(sma(bars, { length: 20 }).sma, reference.sma20, 'sma');
  });

  it('EMA(20) = TA-Lib EMA (SMA-seeded); first defined at bar 19', () => {
    expectMatches(ema(bars, { length: 20 }).ema, reference.ema20, 'ema');
  });

  it('RSI(14) = TA-Lib RSI (Wilder); first defined at bar 14', () => {
    expectMatches(rsi(bars, { length: 14 }).rsi, reference.rsi14, 'rsi');
  });

  it('MACD(12,26,9) = TA-Lib EMA12 − EMA26, signal = TA-Lib EMA9 of it; macd from bar 25, signal/hist from 33', () => {
    const m = macd(bars, { fast: 12, slow: 26, signal: 9 });
    expectMatches(m.macd, reference.macd.macd, 'macd');
    expectMatches(m.signal, reference.macd.signal, 'signal');
    expectMatches(m.hist, reference.macd.hist, 'hist');
  });

  it("MACD converges to TA-Lib's own MACD function once its different fast-EMA seed has washed out", () => {
    const m = macd(bars, { fast: 12, slow: 26, signal: 9 });
    const talib = reference.talibMacd.macd;
    const at = (i: number) => m.macd[i - 25].value - (talib[i] as number);
    expect(Math.abs(at(33))).toBeGreaterThan(0.01); // the seeding difference is real at the start…
    for (let i = 133; i < 300; i++) expect(Math.abs(at(i))).toBeLessThan(1e-5); // …and gone after 100 bars
  });

  it('Bollinger(20, 2) = TA-Lib BBANDS (SMA, population σ); first defined at bar 19', () => {
    const bb = bollinger(bars, { length: 20, stdDevs: 2 });
    expectMatches(bb.upper, reference.bbands20_2.upper, 'upper');
    expectMatches(bb.middle, reference.bbands20_2.middle, 'middle');
    expectMatches(bb.lower, reference.bbands20_2.lower, 'lower');
  });

  it('Stochastic(14, 3, 3) = TA-Lib STOCH (SMA/SMA); %D from bar 17, %K already from bar 15', () => {
    const st = stochastic(bars, { kLength: 14, dLength: 3, smoothing: 3 });
    expectMatches(st.d, reference.stoch14_3_3.d, 'd');
    // TA-Lib reports slowK only from slowD's start (17); ours starts at its own first defined bar, 15
    expect(st.k[0].time).toBe(bars[15].openTime);
    expectMatches(st.k.slice(2), reference.stoch14_3_3.k, 'k');
  });

  it("RSI edge conventions are TA-Lib's: a flat run is 0, an up-only run is 100", () => {
    const run = (closes: number[]) =>
      closes.map((close, i) => ({ ...bars[0], openTime: i * 60_000, open: close, high: close, low: close, close }));
    expect(rsi(run(Array(30).fill(100)), { length: 14 }).rsi.slice(0, 2).map((p) => p.value)).toEqual(reference.edge.rsiFlat14);
    expect(rsi(run(Array.from({ length: 30 }, (_, i) => 100 + i)), { length: 14 }).rsi.slice(0, 2).map((p) => p.value)).toEqual(reference.edge.rsiUp14);
  });
});
